<!-- wp:wdl/lw-space-1 {"pcHeight":16,"tbHeight":16,"spHeight":12} -->
<div class="wp-block-wdl-lw-space-1 lw_space_1"><div class="pc" style="height:16px"></div><div class="tb" style="height:16px"></div><div class="sp" style="height:12px"></div></div>
<!-- /wp:wdl/lw-space-1 -->
<!-- wp:paragraph {"align":"center","style":{"color":{"text":"#1f2b2a"},"typography":{"fontSize":"16px","lineHeight":"2"},"spacing":{"margin":{"top":"28px","bottom":"24px"}}}} -->
<p class="has-text-align-center has-text-color" style="color:#1f2b2a;font-size:16px;line-height:2;margin-top:28px;margin-bottom:24px">30分・無料です。こちらの画面をお見せしながら、いまのやり方をうかがって「合うかどうか」だけお答えします。</p>
<!-- /wp:paragraph -->
<!-- wp:wdl/lw-pr-column-1 {"columnsPc":3,"columnWidthsPc":[1,1,1],"columnsSp":1,"rowGapPc":16,"columnGapPc":16,"rowGapSp":12,"itemBgNone":false,"itemBgTypePc":"solid","itemBgColorPc":"#ffffff","itemBgTypeSp":"solid","itemBgColorSp":"#ffffff","itemBorderColorPc":"#c9dcd7","itemBorderWidthPc":1,"itemBorderStylePc":"solid","itemBorderColorSp":"#c9dcd7","itemBorderWidthSp":1,"itemBorderStyleSp":"solid","itemPaddingTopPc":24,"itemPaddingBottomPc":24,"itemPaddingLeftPc":22,"itemPaddingRightPc":22,"itemPaddingTopSp":20,"itemPaddingBottomSp":20,"itemPaddingLeftSp":18,"itemPaddingRightSp":18,"itemBorderRadiusTopLeftPc":8,"itemBorderRadiusTopRightPc":8,"itemBorderRadiusBottomRightPc":8,"itemBorderRadiusBottomLeftPc":8,"itemBorderRadiusTopLeftSp":8,"itemBorderRadiusTopRightSp":8,"itemBorderRadiusBottomRightSp":8,"itemBorderRadiusBottomLeftSp":8} -->
<div class="wp-block-wdl-lw-pr-column-1 lw-pr-column-1" style="--column-1-wrap-padding-pc:0px 0px 0px 0px;--column-1-wrap-padding-sp:0px 0px 0px 0px;--column-1-border-color-pc:rgb(131, 131, 131);--column-1-border-width-pc:0px;--column-1-border-style-pc:solid;--column-1-border-color-sp:rgb(131, 131, 131);--column-1-border-width-sp:0px;--column-1-border-style-sp:solid;--column-1-bdr-pc:0px 0px 0px 0px;--column-1-bdr-sp:0px 0px 0px 0px;--column-1-gtc-pc:1fr 1fr 1fr;--column-1-gtc-sp:1fr;--column-1-row-gap-pc:16px;--column-1-row-gap-sp:12px;--column-1-column-gap-pc:16px;--column-1-column-gap-sp:16px;--column-1-item-bg-pc:#ffffff;--column-1-item-bg-sp:#ffffff;--column-1-item-min-h-pc:0px;--column-1-item-min-h-sp:0px;--column-1-item-padding-pc:24px 22px 24px 22px;--column-1-item-padding-sp:20px 18px 20px 18px;--column-1-item-bdr-pc:8px 8px 8px 8px;--column-1-item-bdr-sp:8px 8px 8px 8px;--column-1-item-border-color-pc:#c9dcd7;--column-1-item-border-width-pc:1px;--column-1-item-border-style-pc:solid;--column-1-item-border-color-sp:#c9dcd7;--column-1-item-border-width-sp:1px;--column-1-item-border-style-sp:solid"><div class="custom_wrap"><!-- wp:wdl/lw-pr-column-1-item -->
<div class="wp-block-wdl-lw-pr-column-1-item custom_column_item"><!-- wp:heading {"level":3,"style":{"color":{"text":"#063733"},"typography":{"fontSize":"17px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}}} -->
<h3 class="has-text-color" style="color:#063733;font-size:17px;line-height:1.6;margin-top:0px;margin-bottom:16px">用意するもの</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2b2a"},"typography":{"fontSize":"15px","lineHeight":"1.9"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#1f2b2a;font-size:15px;line-height:1.9;margin-top:0px;margin-bottom:0px">パソコンかスマホと、いまお使いのノートや台帳（画面越しに見せていただく必要はありません）。こちらから資料を画面にお出しします。</p>
<!-- /wp:paragraph --></div>
<!-- /wp:wdl/lw-pr-column-1-item -->
<!-- wp:wdl/lw-pr-column-1-item -->
<div class="wp-block-wdl-lw-pr-column-1-item custom_column_item"><!-- wp:heading {"level":3,"style":{"color":{"text":"#063733"},"typography":{"fontSize":"17px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}}} -->
<h3 class="has-text-color" style="color:#063733;font-size:17px;line-height:1.6;margin-top:0px;margin-bottom:16px">話すこと</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2b2a"},"typography":{"fontSize":"15px","lineHeight":"1.9"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#1f2b2a;font-size:15px;line-height:1.9;margin-top:0px;margin-bottom:0px">いまどうやって予約と請求を管理しているか。それを聞いたうえで、<strong>合わないと思ったらその場でそうお伝えします</strong>。</p>
<!-- /wp:paragraph --></div>
<!-- /wp:wdl/lw-pr-column-1-item -->
<!-- wp:wdl/lw-pr-column-1-item -->
<div class="wp-block-wdl-lw-pr-column-1-item custom_column_item"><!-- wp:heading {"level":3,"style":{"color":{"text":"#063733"},"typography":{"fontSize":"17px","lineHeight":"1.6"},"spacing":{"margin":{"top":"0px","bottom":"16px"}}}} -->
<h3 class="has-text-color" style="color:#063733;font-size:17px;line-height:1.6;margin-top:0px;margin-bottom:16px">そのあと</h3>
<!-- /wp:heading -->
<!-- wp:paragraph {"style":{"color":{"text":"#1f2b2a"},"typography":{"fontSize":"15px","lineHeight":"1.9"},"spacing":{"margin":{"top":"0px","bottom":"0px"}}}} -->
<p class="has-text-color" style="color:#1f2b2a;font-size:15px;line-height:1.9;margin-top:0px;margin-bottom:0px">終わったあとに追いかけの連絡はしません。必要になったときにご自身で戻ってきていただければ十分です。</p>
<!-- /wp:paragraph --></div>
